from typing import Any, Dict, Text

from rasa.shared.exceptions import RasaException


def require_keys(data: Dict[Text, Any], *keys: Text, context: Text) -> None:
    """Raise a descriptive error when required dict keys are missing."""
    missing_keys = [key for key in keys if key not in data]
    if missing_keys:
        raise RasaException(
            f"{context} is missing required keys: {', '.join(sorted(missing_keys))}"
        )
